package com.factory.smtquery;

import java.net.URLDecoder;
import java.util.*;
import org.json.*;

public final class QueryServiceDemoTest {
 static void ok(boolean value,String message){if(!value)throw new AssertionError(message);}
 static QueryService service(QueryService.Config config,QueryService.Transport transport){return new QueryService(config,(o,raw,demo)->{},transport);}

 public static void main(String[] args)throws Exception{
  QueryService.Config demo=new QueryService.Config();demo.demo=true;demo.mes="";demo.validate();
  final int[] network={0};QueryService s=service(demo,(url,timeout)->{network[0]++;throw new AssertionError("demo mode called network: "+url);});
  ok(s.orders().values.size()==2,"demo orders");QueryService.Order order=s.orders().values.get(1);ok(s.load(order).getJSONArray("LOAD_SUBS").length()==3,"demo load");ok(s.scan("DEMO001",order,s.load(order)).size()==2,"demo location match");
  QueryService.LoadInfo load=s.loadDid("126073000644561");ok(load.packageQty==10000,"demo WMS single-package quantity");ok(s.submitShortage(load,3).contains("30000"),"demo shortage quantity must equal package qty times reels");
  QueryService.MaterialLocations demoLocations=s.storageLocations("15435229-00");ok(demoLocations.locations.size()==3&&demoLocations.total==500&&"A001".equals(demoLocations.locations.get(0).storeCode)&&demoLocations.locations.get(0).availableQty==200,"demo storeCode aggregation without network");
  List<QueryService.Shortage> shortages=s.shortages();ok(shortages.size()==3,"demo shortage list");QueryService.IssueMaterials demoMaterials=s.issueMaterials(shortages.get(0));ok(demoMaterials.values.size()==2&&demoMaterials.contains("13247855-00")&&demoMaterials.contains("15435229-00"),"demo main and substitute materials");QueryService.PackageInfo p1=s.packageInfo("CT06260829529001"),p2=s.packageInfo("DEMO-ALT-2");ok(p1.qty==189&&p2.qty==61,"demo package quantities");ok(s.postIssue(shortages.get(0),Arrays.asList(p1,p2),"7179842",demoMaterials).completed&&p2.substitute,"demo substitute issue submit");ok(network[0]==0,"demo mode must not call network");

  boolean mismatch=false;try{s.postIssue(shortages.get(1),Collections.singletonList(p1),"7179842");}catch(Exception e){mismatch=e.getMessage().contains("不在当前站位可发料号清单");}ok(mismatch,"bpn outside issue material list must fail");

  QueryService.Config live=new QueryService.Config();final List<String> getCalls=new ArrayList<>(),wmsPostCalls=new ArrayList<>(),mesPostCalls=new ArrayList<>();final boolean[] failSecond={false};QueryService.Transport liveTransport=new QueryService.Transport(){public String get(String url,int timeout)throws Exception{getCalls.add(URLDecoder.decode(url,"UTF-8"));return "{\"RESULT\":\"PASS\"}";}public String post(String url,String body,int timeout)throws Exception{String decoded=URLDecoder.decode(url,"UTF-8");if(decoded.contains("method=GetLoadByShoporderAndLine")){mesPostCalls.add(decoded+" BODY="+body);return "{\"RESULT\":\"PASS\",\"LOAD\":{\"LOAD_SUBS\":[{\"bydpn\":\"13247855-00\",\"location\":\"12-4E\"},{\"bydpn\":\"15435229-00\",\"location\":\"12-4E\"},{\"bydpn\":\"OTHER\",\"location\":\"99-1\"}]}}";}wmsPostCalls.add(url+" BODY="+body);if(failSecond[0]&&body.contains("CT06260829529002"))return "{\"RESULT\":\"FAIL\",\"MESSAGE\":\"模拟移储失败\"}";return "{\"RESULT\":\"PASS\"}";}};QueryService liveService=service(live,liveTransport);
  liveService.submitShortage(load,3);ok(getCalls.get(getCalls.size()-1).contains("\"DEMAND_QTY\":\"30000\""),"MatShortage must use WMS package qty times reels");
  QueryService.IssueMaterials liveMaterials=liveService.issueMaterials(shortages.get(0));ok(liveMaterials.values.size()==2&&liveMaterials.hasAlternatives(),"location must resolve main and substitute materials");ok(mesPostCalls.size()==1&&mesPostCalls.get(0).contains("method=GetLoadByShoporderAndLine")&&mesPostCalls.get(0).contains("\"SHOPORDER\":\"5030059140T\"")&&mesPostCalls.get(0).contains("\"LINE\":\"H5-2F-S02\"")&&mesPostCalls.get(0).contains("\"LOGIN_ID\":-1")&&mesPostCalls.get(0).contains("\"CLIENT_ID\":1"),"substitute query must POST selected task parameters");
  QueryService.PackageInfo lp1=s.packageInfo("CT06260829529001"),lp2=s.packageInfo("CT06260829529002");lp2.bpn="15435229-00";QueryService.IssueResult issued=liveService.postIssue(shortages.get(0),Arrays.asList(lp1,lp2),"7179842",liveMaterials);ok(issued.completed&&lp2.substitute,"main and substitute WMS moves should complete");ok(wmsPostCalls.size()==2,"each package must call getInfoAndMoveStorage once");ok(wmsPostCalls.get(0).contains("/wmsMoveStorage/getInfoAndMoveStorage")&&wmsPostCalls.get(0).contains("\"warehouseId\":\"20117901\"")&&wmsPostCalls.get(0).contains("\"userName\":\"7179842\""),"WMS move URL and body");ok(getCalls.get(getCalls.size()-1).contains("\"PULL_OUT_DID\":\"CT06260829529001,CT06260829529002\""),"PULL_OUT_DID comma join");

  QueryService.PackageInfo f1=s.packageInfo("CT06260829529001"),f2=s.packageInfo("CT06260829529002");wmsPostCalls.clear();int mesBefore=getCalls.size();failSecond[0]=true;QueryService.IssueResult partial=liveService.postIssue(shortages.get(0),Arrays.asList(f1,f2),"7179842",liveMaterials);ok(!partial.completed&&partial.failures.size()==1&&partial.failures.get(0).contains("CT06260829529002"),"failed packages must be collected after all WMS calls");ok(wmsPostCalls.size()==2&&f1.moved&&!f2.moved,"successful package is recorded and failed package remains retryable");ok(getCalls.size()==mesBefore,"MatPost must wait until all WMS moves succeed");failSecond[0]=false;wmsPostCalls.clear();QueryService.IssueResult retried=liveService.postIssue(shortages.get(0),Arrays.asList(f1,f2),"7179842",liveMaterials);ok(retried.completed&&wmsPostCalls.size()==1,"retry skips packages already moved successfully");
  QueryService.Config warehouseConfig=new QueryService.Config();warehouseConfig.warehouseId="20118888";final List<String> wmsUrls=new ArrayList<>();QueryService warehouseService=service(warehouseConfig,(url,timeout)->{wmsUrls.add(URLDecoder.decode(url,"UTF-8"));return "{\"RESULT\":\"PASS\",\"DATA\":[{\"packingNum\":\"PKG001\",\"bpn\":\"13247855-00\",\"qty\":100}]}";});
  warehouseService.packageInfo("PKG001");ok(wmsUrls.get(0).contains("warehouseId=20118888"),"issue WMS request must include configured warehouseId");
  JSONObject loadTable=new JSONObject().put("LOAD","L1").put("LOAD_SUBS",new JSONArray().put(new JSONObject().put("bydpn","13247855-00").put("location","1-01").put("description","demo").put("station","SMT")));
  warehouseService.scan("PKG001",new QueryService.Order(warehouseConfig.lines.get(0),"4311563736"),loadTable);ok(wmsUrls.get(1).contains("warehouseId=20118888"),"query WMS request must include configured warehouseId");
  final List<String> inventoryRequests=new ArrayList<>();QueryService inventoryService=service(warehouseConfig,new QueryService.Transport(){public String get(String url,int timeout){throw new AssertionError("inventory must POST");}public String post(String url,String body,int timeout){inventoryRequests.add(url+" BODY="+body);return "{\"RESULT\":\"PASS\",\"DATA\":{\"page\":[{\"mergeBpn\":\"MAT-1\",\"storeCode\":\"A001\",\"storeLocation\":\"UPPER-1\",\"warehouseAvailableQty\":100},{\"mergeBpn\":\"MAT-1\",\"storeCode\":\"A001\",\"storeLocation\":\"UPPER-2\",\"warehouseAvailableQty\":100},{\"mergeBpn\":\"MAT-1\",\"storeCode\":\"B002\",\"storeLocation\":\"UPPER-2\",\"warehouseAvailableQty\":50},{\"mergeBpn\":\"MAT-1\",\"storeLocation\":\"UPPER-3\",\"warehouseAvailableQty\":0}]}}";}});QueryService.MaterialLocations locations=inventoryService.storageLocations("MAT-1");ok(locations.locations.size()==2&&locations.total==250&&"A001".equals(locations.locations.get(0).storeCode)&&locations.locations.get(0).availableQty==200&&locations.locations.get(0).storeLocation.contains("UPPER-1")&&locations.locations.get(0).storeLocation.contains("UPPER-2"),"packages must be grouped by storeCode even when storeLocation differs");ok(inventoryRequests.get(0).contains("/wms3.0/ms/exi/wmsMaterialStore/getPage")&&inventoryRequests.get(0).contains("\"factory\":\"CT21\"")&&inventoryRequests.get(0).contains("\"warehouseId\":\"20118888\"")&&inventoryRequests.get(0).contains("\"mergeBpn\":\"MAT-1\"")&&inventoryRequests.get(0).contains("\"storeStatus\":\"已上架\""),"inventory endpoint and request parameters");
  QueryService.Config restored=QueryService.Config.parse(warehouseConfig.json().toString());ok("20118888".equals(restored.warehouseId),"warehouseId must persist in config");ok("PRODUCTION".equals(restored.environment)&&restored.wmsIssueUrl().contains("10.128.30.78:20018"),"production WMS environment must persist");restored.environment="TEST";ok(restored.wmsIssueUrl().equals("http://10.12.5.188:20016/wms3.0/wms/exi/wmsMoveStorage/getInfoAndMoveStorage"),"test WMS move endpoint");ok(restored.wmsQueryUrl().equals("http://10.12.5.188:20016/wms3.0/wms/exi/wmsMaterialStore/getListByPackingNum"),"test WMS query endpoint");
  System.out.println("QueryServiceDemoTest PASS");
 }
}
